import PyU4V, json, time

def protect_storage_group(sg_name, change_id, ttl_hours=24, dry_run=True):
    conn = PyU4V.U4VConn()
    snap_name = f'{change_id}-{int(time.time())}'
    result = {'storage_group': sg_name, 'snapshot': snap_name, 'dry_run': dry_run}

    if not conn.snapshot.is_snapvx_licensed():
        raise RuntimeError('SnapVX is not licensed on this array')

    if not dry_run:
        conn.snapshot.create_storage_group_snapshot(sg_name, snap_name, ttl=ttl_hours, hours=True)
        snaps = conn.snapshot.get_storage_group_snapshot_list(sg_name)
        result['snapshot_visible'] = snap_name in snaps

    return result
